val (i, n) = loops.lastOrNull() ?: return null
return when (name) {
    "@index" -> NumberValue(i.toLong())
    "@number" -> NumberValue(i + 1L)
    "@first" -> BooleanValue(i == 0)
    else -> BooleanValue(i == n - 1)
            val found = resolve(expr.name, contexts, loops)
            if (strict && tag.kind in "v&" && found == null)
                throw Problem("missing '${expr.name}'")
            var value: Value = found ?: Absent
            for (filter in expr.filters) value = applyFilter(value, filter)
                } else if (value is ListValue) {
                    for ((i, item) in value.values.withIndex()) append(
                        render(
                            tags,
                            at + 1,
                            tag.end,
                            contexts + item,
                            loops + (i to value.values.size),
                            partials,
                            strict,
                            depth,
                        ),
                    )
